def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """ Count the number of integers x such that num1 <= x <= num2 and 
    min_sum <= digit_sum(x) <= max_sum, where digit_sum(x) is the sum of digits of x.

    Return the count modulo 10^9 + 7.

    Args:
        num1: A numeric string representing the lower bound (1 <= num1 <= 10^22)
        num2: A numeric string representing the upper bound (num1 <= num2 <= 10^22)
        min_sum: The minimum allowed digit sum (1 <= min_sum <= 400)
        max_sum: The maximum allowed digit sum (min_sum <= max_sum <= 400)

    Returns:
        The number of good integers modulo 10^9 + 7
    """
    from functools import lru_cache

    def digit_sum(x):
        return sum(int(d) for d in x)

    def count_up_to(n_str, min_sum, max_sum):
        @lru_cache(maxsize=None)
        def dp(pos, tight, sum_so_far, leading_zero):
            if pos == len(n_str):
                return 1 if min_sum <= sum_so_far <= max_sum else 0
            limit = int(n_str[pos]) if tight else 9
            total = 0
            for d in range(0, limit + 1):
                new_tight = tight and (d == limit)
                new_sum = sum_so_far + d
                new_leading_zero = leading_zero and (d == 0)
                if not new_leading_zero:
                    new_sum = sum_so_far + d
                total += dp(pos + 1, new_tight, new_sum, new_leading_zero)
            return total % MOD

        return dp(0, True, 0, True)

    def count_between(a, b):
        return (count_up_to(b, min_sum, max_sum) - count_up_to(a, min_sum, max_sum)) % MOD

    return count_between(num1, num2)

